#include "nodeagent.h"
#include <QCoreApplication>
#include <QCommandLineParser>
#include <QTimer>
#include <QDebug>
#include <csignal>
namespace {volatile std::sig_atomic_t stopped=0;void Stop(int){stopped=1;}}
int main(int argc,char **argv){QCoreApplication app(argc,argv);QCoreApplication::setOrganizationName("GetDAQ");QCoreApplication::setApplicationName("getdaq-node-agent");QCommandLineParser parser;parser.addHelpOption();parser.addOption({"config","Private node.json configuration.","path"});parser.addOption({"renew-pairing","Renew a local unpaired node invitation; requires --config."});parser.addOption({"initialize","Create a new private node directory and pairing invitation.","directory"});parser.addOption({"programs","Installed service bin directory.","directory",QCoreApplication::applicationDirPath()});parser.addOption({"bind","Management IPv4 on this host.","IPv4","127.0.0.1"});parser.addOption({"port","Management HTTPS port.","port","24260"});parser.addOption({"data","Local data parent directory.","directory"});parser.process(app);try{if(parser.isSet("initialize")){Deployment::InitializeNode(parser.value("initialize"),parser.value("programs"),parser.value("bind"),parser.value("port").toInt(),parser.value("data"));qInfo().noquote()<<"Node initialized. Pairing invitation is in pairing.json; credentials are not displayed.";return 0;}Deployment::Require(parser.isSet("config"),"Supply --config or --initialize");if(parser.isSet("renew-pairing")){Deployment::RenewNodePairing(parser.value("config"));qInfo()<<"Local pairing invitation renewed; value not displayed.";return 0;}std::signal(SIGPIPE,SIG_IGN);std::signal(SIGINT,Stop);std::signal(SIGTERM,Stop);Deployment::NodeAgent service(parser.value("config"));service.Start();qInfo()<<"GetDAQ node agent ready; HTTPS; no hardware commands sent.";QTimer timer;QObject::connect(&timer,&QTimer::timeout,&app,[&]{if(stopped)app.quit();});timer.start(100);return app.exec();}catch(const std::exception &error){qCritical().noquote()<<error.what();return 1;}}
